def load_bundled_module(bundle_key):
    """Decode one embedded source module without writing temporary files."""
    encoded = BUNDLED_SOURCES[bundle_key].encode("ascii")
    source = zlib.decompress(base64.b85decode(encoded)).decode("utf-8")

    module_name = "farmwar_bundle_" + bundle_key
    module = types.ModuleType(module_name)
    module.__file__ = os.path.join(SCRIPT_DIR, "<bundled_" + bundle_key + ".py>")
    module.__package__ = ""
    sys.modules[module_name] = module

    code = compile(source, "<bundled:" + bundle_key + ">", "exec")
    exec(code, module.__dict__)
    return module


def main():
    print("\n=== Loading Standalone FarmWar Showcase Bundle ===\n")

    modules = {
        key: load_bundled_module(key)
        for key in (
            "basic_characters",
            "seven_roles",
            "signal_towers",
            "cooking_machine",
            "medicine_pistol",
        )
    }
    orchestrator = load_bundled_module("showcase_orchestrator")

    # Replace the orchestrator's filesystem source lookup with the already
    # decoded in-memory modules. Its scene layout/render logic remains exactly
    # the same as the modular version.
    orchestrator.resolve_source = lambda label: label
    orchestrator.load_python_module = lambda module_name, label: modules[label]
    orchestrator.SOURCE_CANDIDATES = {
        key: (key,)
        for key in modules
    }

    # All user-facing outputs remain beside this standalone script.
    orchestrator.SCRIPT_DIR = SCRIPT_DIR
    orchestrator.OUTPUT_DIR = os.path.join(SCRIPT_DIR, "generated_showcase")
    orchestrator.OUTPUT_BLEND = os.path.join(
        orchestrator.OUTPUT_DIR,
        "FTF_RolesAndTools_Showcase.blend",
    )
    orchestrator.OUTPUT_PNG = os.path.join(
        orchestrator.OUTPUT_DIR,
        "FTF_RolesAndTools_Showcase.png",
    )

    orchestrator.main()


if __name__ == "__main__":
    main()
